package game.ui;

import game.model.GearPiece;
import game.model.Item;
import game.model.Material;

import javax.imageio.ImageIO;
import javax.swing.*;
import java.awt.*;
import java.awt.geom.Line2D;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;
import java.io.InputStream;
import java.util.HashMap;
import java.util.Map;
import java.util.Random;

/**
 * Pencil-drawn icons for items (images/items/{icon}.png), augment categories (images/augments/{key}.png)
 * and forging materials (images/materials/{icon}.png), generated by tools/pencil-art. Scaled copies are
 * cached per size.
 */
public final class ItemArt {
    private static final Map<String, BufferedImage> SOURCES = new HashMap<>();
    private static final Map<String, ImageIcon> SCALED = new HashMap<>();
    private static final String MATERIALS = "images/materials/";
    /** Prefixes on a picture's path asking for a version made from it. */
    private static final String ERASED = "erased:";
    private static final String RUBBED = "rubbed:";
    private static final String PENCILED = "penciled:";

    private ItemArt() {}

    /** The item's icon at size x size, or null if it has none. */
    public static ImageIcon item(Item item, int size) {
        return item == null || item.getIcon() == null ? null : scaled("images/items/" + item.getIcon() + ".png", size);
    }

    /** A piece of gear's icon: its item's, or the rubbed-out version once it is destroyed. */
    public static ImageIcon piece(GearPiece piece, int size) {
        Item item = piece.getItem();
        if (!piece.isDestroyed() || item.getIcon() == null) return item(item, size);
        return scaled(ERASED + "images/items/" + item.getIcon() + ".png", size);
    }

    /** The item in plain graphite, whole: what restoring draws. */
    public static ImageIcon penciled(Item item, int size) {
        return scaled(PENCILED + "images/items/" + item.getIcon() + ".png", size);
    }

    /** The item in plain graphite with the eraser's strokes taken out, and nothing lying on top. */
    public static ImageIcon rubbed(Item item, int size) {
        return scaled(RUBBED + "images/items/" + item.getIcon() + ".png", size);
    }

    /** A non-item picture from the same folder (treasure chests, quest scroll, inn bed). */
    public static ImageIcon misc(String key, int size) {
        return scaled("images/items/" + key + ".png", size);
    }

    public static ImageIcon augment(String key, int size) {
        return scaled("images/augments/" + key + ".png", size);
    }

    public static ImageIcon material(Material material, int size) {
        return scaled(MATERIALS + material.getIcon() + ".png", size);
    }

    private static ImageIcon scaled(String path, int size) {
        String key = path + "@" + size;
        if (SCALED.containsKey(key)) return SCALED.get(key);
        BufferedImage src = SOURCES.computeIfAbsent(path, ItemArt::load);
        ImageIcon icon = src == null ? null : new ImageIcon(shrink(src, size));
        SCALED.put(key, icon);
        return icon;
    }

    /** Halves step by step before the last bilinear pass, so thin pencil lines stay visible. */
    private static BufferedImage shrink(BufferedImage src, int size) {
        BufferedImage cur = src;
        while (cur.getWidth() / 2 >= size) cur = resize(cur, cur.getWidth() / 2);
        return resize(cur, size);
    }

    private static BufferedImage resize(BufferedImage src, int size) {
        BufferedImage out = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = out.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
        g.drawImage(src, 0, 0, size, size, null);
        g.dispose();
        return out;
    }

    /** The picture in plain graphite: color out, lifted a little toward paper. */
    private static BufferedImage penciled(BufferedImage src) {
        if (src == null) return null;
        int w = src.getWidth(), h = src.getHeight();
        BufferedImage out = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
        for (int y = 0; y < h; y++) {
            for (int x = 0; x < w; x++) {
                int argb = src.getRGB(x, y);
                int r = (argb >> 16) & 255, g = (argb >> 8) & 255, b = argb & 255;
                int gray = 56 + (r * 30 + g * 59 + b * 11) * 170 / 25500;
                out.setRGB(x, y, (argb & 0xFF000000) | gray << 16 | gray << 8 | gray);
            }
        }
        return out;
    }

    /** Back-and-forth eraser strokes through the middle only, so both ends still show what it was. */
    private static BufferedImage rubbed(String path, BufferedImage src) {
        BufferedImage out = penciled(src);
        if (out == null) return null;
        int w = out.getWidth(), h = out.getHeight();
        Random rnd = new Random(path.hashCode());
        Graphics2D g = out.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setComposite(AlphaComposite.getInstance(AlphaComposite.DST_OUT, 0.96f));
        g.setStroke(new BasicStroke(w * 0.075f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        Path2D rub = new Path2D.Double();
        int passes = 5;
        for (int i = 0; i <= passes; i++) {
            double t = i / (double) passes;
            double x = w * (0.32 + 0.3 * t) + (rnd.nextDouble() - 0.5) * w * 0.03;
            double y = (i % 2 == 0 ? h * 0.74 : h * 0.26) + (rnd.nextDouble() - 0.5) * h * 0.06;
            if (i == 0) rub.moveTo(x, y);
            else rub.lineTo(x, y);
        }
        g.draw(rub);
        g.dispose();
        return out;
    }

    /**
     * The icon of a destroyed piece: rubbed out, with crumbs left behind and the eraser sitting in the
     * corner. Seeded by the path, so a piece looks the same every time.
     */
    private static BufferedImage rubbedOut(String path, BufferedImage src) {
        BufferedImage out = rubbed(path, src);
        if (out == null) return null;
        int w = out.getWidth(), h = out.getHeight();
        Random rnd = new Random(path.hashCode() + 1L);
        Graphics2D g = out.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setStroke(new BasicStroke(w * 0.02f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        for (int i = 0; i < 5; i++) {
            double x = w * (0.3 + 0.3 * rnd.nextDouble()), y = h * (0.82 + 0.12 * rnd.nextDouble());
            double a = rnd.nextDouble() * Math.PI, len = w * (0.03 + 0.03 * rnd.nextDouble());
            g.setColor(new Color(240, 148, 168));
            g.draw(new Line2D.Double(x, y, x + Math.cos(a) * len, y + Math.sin(a) * len));
        }
        BufferedImage eraser = load(MATERIALS + Material.ERASER_DUST.getIcon() + ".png");
        if (eraser != null) {
            int size = w * 2 / 5;
            g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
            g.drawImage(eraser, w - size, h - size, size, size, null);
        }
        g.dispose();
        return out;
    }

    private static BufferedImage load(String path) {
        if (path.startsWith(ERASED)) {
            String original = path.substring(ERASED.length());
            return rubbedOut(original, load(original));
        }
        if (path.startsWith(RUBBED)) {
            String original = path.substring(RUBBED.length());
            return rubbed(original, load(original));
        }
        if (path.startsWith(PENCILED)) return penciled(load(path.substring(PENCILED.length())));
        try (InputStream in = ItemArt.class.getResourceAsStream(path)) {
            if (in != null) return ImageIO.read(in);
        } catch (Exception ignored) {
            // Missing icon: callers show the text without it.
        }
        return null;
    }
}
